'use client'

import { useState, useRef } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import Image from 'next/image'
import { supabase } from '@/lib/supabase'
import { useAuth } from '@/contexts/AuthContext'
import { useBrands, Brand, CreateBrandInput } from '@/hooks/useBrands'
import {
    Plus, Settings, Trash2, Loader2, ExternalLink,
    Briefcase, ChevronDown, LogOut
} from 'lucide-react'

// ============================================
// CONSTANTS
// ============================================

const GOOGLE_FONTS = [
    { label: 'Geist', value: 'Geist', category: 'Sans Serif' },
    { label: 'Inter', value: 'Inter', category: 'Sans Serif' },
    { label: 'Roboto', value: 'Roboto', category: 'Sans Serif' },
    { label: 'Poppins', value: 'Poppins', category: 'Sans Serif' },
    { label: 'Merriweather', value: 'Merriweather', category: 'Serif' },
    { label: 'Playfair Display', value: 'Playfair Display', category: 'Serif' },
    { label: 'JetBrains Mono', value: 'JetBrains Mono', category: 'Monospace' }
]

const COLOR_PRESETS = ['#0066FF', '#000000', '#FF3366', '#00CC66', '#7C3AED', '#F59E0B']

// ============================================
// MAIN COMPONENT
// ============================================

export default function BrandsDashboard() {
    const router = useRouter()

    // Auth state
    const {
        user,
        currentWorkspace,
        workspaces,
        switchWorkspace,
        signOut,
        loading: authLoading,
        workspacesLoading
    } = useAuth()

    // Brands from hook
    const { brands, loading: brandsLoading, error, createBrand, deleteBrand, fetchBrands } = useBrands()

    // UI state
    const [filter, setFilter] = useState<'all' | 'published' | 'draft'>('all')
    const [showNewModal, setShowNewModal] = useState(false)
    const [showDeleteConfirm, setShowDeleteConfirm] = useState<{ id: string; name: string } | null>(null)
    const [creating, setCreating] = useState(false)

    // New brand form
    const [newBrandForm, setNewBrandForm] = useState({
        name: '',
        color: '#0066FF',
        font: 'Geist',
        bannerUrl: null as string | null
    })

    // File inputs
    const bannerInputRef = useRef<HTMLInputElement>(null)

    // ============================================
    // COMPUTED
    // ============================================

    const filteredBrands = brands.filter(brand => {
        if (filter === 'all') return true
        const isPublished = brand.published != null
        return filter === 'published' ? isPublished : !isPublished
    })

    const isLoading = authLoading || workspacesLoading

    // ============================================
    // HANDLERS
    // ============================================

    const handleCreateBrand = async () => {
        if (!newBrandForm.name.trim()) return

        setCreating(true)
        try {
            const input: CreateBrandInput = {
                name: newBrandForm.name.trim(),
                primary_color: newBrandForm.color,
                font_family: newBrandForm.font,
                banner_url: newBrandForm.bannerUrl || undefined
            }

            const { data, error } = await createBrand(input)

            if (error) throw error

            setShowNewModal(false)
            setNewBrandForm({ name: '', color: '#0066FF', font: 'Geist', bannerUrl: null })

            if (data) {
                router.push(`/admin/brand/${data.id}/introduction`)
            }
        } catch (err: any) {
            alert('Failed to create brand: ' + err.message)
        } finally {
            setCreating(false)
        }
    }

    const handleDeleteBrand = async () => {
        if (!showDeleteConfirm) return

        try {
            const { error } = await deleteBrand(showDeleteConfirm.id)
            if (error) throw error
            setShowDeleteConfirm(null)
        } catch (err: any) {
            alert('Failed to delete: ' + err.message)
        }
    }

    const handleBannerUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        try {
            const ext = file.name.split('.').pop()
            const path = `banners/${Date.now()}.${ext}`

            const { error } = await supabase.storage.from('brand-assets').upload(path, file)
            if (error) throw error

            const { data } = supabase.storage.from('brand-assets').getPublicUrl(path)
            setNewBrandForm(prev => ({ ...prev, bannerUrl: data.publicUrl }))
        } catch (err: any) {
            alert('Upload failed: ' + err.message)
        }
    }

    // ============================================
    // REMOVED: No more blocking loading spinner
    // Content shows immediately - no endless loading
    // ============================================

    // ============================================
    // RENDER
    // ============================================

    return (
        <div className="flex min-h-screen bg-gray-50">
            {/* Sidebar */}
            <aside className="hidden md:flex w-64 bg-white border-r border-gray-100 flex-shrink-0 flex-col fixed top-0 bottom-0 left-0 z-30">
                <div className="p-6">
                    <div className="flex items-center gap-2 font-bold text-xl mb-8">
                        <Image src="/guidr-logo.png" alt="Guidr" width={120} height={32} priority />
                    </div>

                    <nav className="space-y-1">
                        <SidebarItem icon={Briefcase} label="Brand Guidelines" active />
                        <Link href="/admin/settings" className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 hover:bg-gray-50 text-sm font-medium">
                            <Settings size={18} />
                            Settings
                        </Link>
                    </nav>
                </div>

                {/* User Section */}
                <div className="mt-auto p-4 border-t border-gray-100 space-y-3">
                    {/* Workspace Switcher */}
                    {workspaces.length > 0 && (
                        <div className="relative group">
                            <button className="flex items-center gap-2 w-full p-2 hover:bg-gray-50 rounded-lg text-sm font-medium text-gray-600">
                                <div className="w-6 h-6 rounded bg-gradient-to-br from-indigo-500 to-purple-500 flex items-center justify-center text-white text-xs font-bold">
                                    {currentWorkspace?.name?.charAt(0) || 'W'}
                                </div>
                                <span className="flex-1 text-left truncate">{currentWorkspace?.name || 'Workspace'}</span>
                                <ChevronDown size={14} />
                            </button>

                            {/* Dropdown - shown on hover */}
                            <div className="absolute bottom-full left-0 right-0 mb-1 bg-white border border-gray-200 rounded-lg shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all">
                                {workspaces.map(ws => (
                                    <button
                                        key={ws.id}
                                        onClick={() => switchWorkspace(ws.id)}
                                        className={`w-full px-3 py-2 text-left text-sm hover:bg-gray-50 ${ws.id === currentWorkspace?.id ? 'bg-gray-50 font-medium' : ''}`}
                                    >
                                        {ws.name}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* User Profile */}
                    <div className="flex items-center gap-3 p-2">
                        <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-purple-500 to-pink-500 flex items-center justify-center text-white text-sm font-medium">
                            {user?.email?.charAt(0)?.toUpperCase() || 'U'}
                        </div>
                        <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium text-gray-900 truncate">{user?.email}</p>
                            <p className="text-xs text-gray-400 truncate">{currentWorkspace?.role || 'Member'}</p>
                        </div>
                        <button
                            onClick={() => signOut()}
                            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded"
                            title="Sign out"
                        >
                            <LogOut size={16} />
                        </button>
                    </div>
                </div>
            </aside>

            {/* Main Content */}
            <main className="flex-1 md:ml-64 p-4 md:p-8">
                {/* Header */}
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-1 bg-white p-1 rounded-xl border border-gray-200 shadow-sm">
                        {(['all', 'published', 'draft'] as const).map(f => (
                            <button
                                key={f}
                                onClick={() => setFilter(f)}
                                className={`px-4 py-2 capitalize font-medium rounded-lg text-sm transition-all ${filter === f ? 'bg-gray-100 text-gray-900' : 'text-gray-500 hover:bg-gray-50'
                                    }`}
                            >
                                {f === 'draft' ? 'Drafts' : f === 'all' ? 'All' : 'Published'}
                            </button>
                        ))}
                    </div>

                    <button
                        onClick={() => setShowNewModal(true)}
                        className="flex items-center gap-2 px-6 py-2.5 bg-gray-900 text-white font-medium rounded-full hover:bg-gray-800 transition-all shadow-sm"
                    >
                        <Plus size={18} />
                        Create
                    </button>
                </div>

                {/* Error Display */}
                {error && (
                    <div className="bg-red-50 border border-red-200 rounded-xl p-4 mb-6">
                        <p className="text-sm text-red-700">{error}</p>
                    </div>
                )}

                {/* Loading */}
                {/* Loading Skeletons */}
                {brandsLoading && (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {[1, 2, 3, 4, 5, 6].map(i => (
                            <BrandCardSkeleton key={i} />
                        ))}
                    </div>
                )}

                {/* Brands Grid - Only show after loading completes */}
                {!brandsLoading && (
                    <>
                        {filteredBrands.length === 0 ? (
                            <EmptyState filter={filter} onCreate={() => setShowNewModal(true)} />
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {filteredBrands.map(brand => (
                                    <BrandCard
                                        key={brand.id}
                                        brand={brand}
                                        onClick={() => router.push(`/admin/brand/${brand.id}/introduction`)}
                                        onDelete={() => setShowDeleteConfirm({ id: brand.id, name: brand.name })}
                                    />
                                ))}
                            </div>
                        )}
                    </>
                )}
            </main>

            {/* Create Modal */}
            {showNewModal && (
                <Modal onClose={() => setShowNewModal(false)} title="Create Brand Guideline">
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Brand Name</label>
                            <input
                                type="text"
                                value={newBrandForm.name}
                                onChange={e => setNewBrandForm(prev => ({ ...prev, name: e.target.value }))}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                placeholder="My Brand"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Primary Color</label>
                            <div className="flex gap-2">
                                {COLOR_PRESETS.map(color => (
                                    <button
                                        key={color}
                                        onClick={() => setNewBrandForm(prev => ({ ...prev, color }))}
                                        className={`w-8 h-8 rounded-full border-2 ${newBrandForm.color === color ? 'border-gray-900' : 'border-transparent'}`}
                                        style={{ backgroundColor: color }}
                                    />
                                ))}
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Font</label>
                            <select
                                value={newBrandForm.font}
                                onChange={e => setNewBrandForm(prev => ({ ...prev, font: e.target.value }))}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg"
                            >
                                {GOOGLE_FONTS.map(font => (
                                    <option key={font.value} value={font.value}>{font.label}</option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Banner (optional)</label>
                            <input
                                ref={bannerInputRef}
                                type="file"
                                accept="image/*"
                                onChange={handleBannerUpload}
                                className="hidden"
                            />
                            {newBrandForm.bannerUrl ? (
                                <div className="relative h-24 rounded-lg overflow-hidden">
                                    <img src={newBrandForm.bannerUrl} alt="" className="w-full h-full object-cover" />
                                    <button
                                        onClick={() => setNewBrandForm(prev => ({ ...prev, bannerUrl: null }))}
                                        className="absolute top-2 right-2 p-1 bg-white rounded-full shadow"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                </div>
                            ) : (
                                <button
                                    onClick={() => bannerInputRef.current?.click()}
                                    className="w-full py-4 border-2 border-dashed border-gray-200 rounded-lg text-gray-500 hover:border-gray-300"
                                >
                                    Upload Banner
                                </button>
                            )}
                        </div>

                        <div className="flex gap-3 pt-4">
                            <button
                                onClick={() => setShowNewModal(false)}
                                className="flex-1 py-2 border border-gray-200 rounded-lg font-medium"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleCreateBrand}
                                disabled={!newBrandForm.name.trim() || creating}
                                className="flex-1 py-2 bg-gray-900 text-white rounded-lg font-medium disabled:opacity-50"
                            >
                                {creating ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : 'Create'}
                            </button>
                        </div>
                    </div>
                </Modal>
            )}

            {/* Delete Confirmation */}
            {showDeleteConfirm && (
                <Modal onClose={() => setShowDeleteConfirm(null)} title="Delete Brand">
                    <p className="text-gray-600 mb-6">
                        Are you sure you want to delete <strong>{showDeleteConfirm.name}</strong>? This cannot be undone.
                    </p>
                    <div className="flex gap-3">
                        <button
                            onClick={() => setShowDeleteConfirm(null)}
                            className="flex-1 py-2 border border-gray-200 rounded-lg font-medium"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleDeleteBrand}
                            className="flex-1 py-2 bg-red-600 text-white rounded-lg font-medium hover:bg-red-700"
                        >
                            Delete
                        </button>
                    </div>
                </Modal>
            )}
        </div>
    )
}

// ============================================
// SUB-COMPONENTS
// ============================================

function SidebarItem({ icon: Icon, label, active }: { icon: any; label: string; active?: boolean }) {
    return (
        <div className={`flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium ${active ? 'bg-gray-100 text-gray-900' : 'text-gray-600 hover:bg-gray-50'}`}>
            <Icon size={18} />
            {label}
        </div>
    )
}

function EmptyState({ filter, onCreate }: { filter: string; onCreate: () => void }) {
    return (
        <div className="text-center py-32 bg-white rounded-2xl border border-dashed border-gray-300">
            <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center mx-auto mb-4">
                <Plus className="w-8 h-8 text-gray-400" />
            </div>
            <h3 className="text-lg font-medium text-gray-900">
                {filter === 'all' ? 'No brand guidelines yet' : `No ${filter} projects`}
            </h3>
            <p className="text-gray-500 mb-6">
                {filter === 'all' ? 'Create your first brand project.' : `You don't have any ${filter} projects.`}
            </p>
            <button onClick={onCreate} className="text-indigo-600 font-medium hover:underline">
                Create now
            </button>
        </div>
    )
}

function BrandCard({ brand, onClick, onDelete }: { brand: Brand; onClick: () => void; onDelete: () => void }) {
    return (
        <div
            className="group bg-white rounded-2xl border border-gray-200 overflow-hidden hover:shadow-xl transition-all cursor-pointer"
            onClick={onClick}
        >
            {/* Banner */}
            <div className="relative h-32 bg-gradient-to-br from-gray-100 to-gray-200">
                {brand.banner_url && (
                    <img src={brand.banner_url} alt="" className="w-full h-full object-cover" />
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

                {/* Actions */}
                <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button
                        onClick={e => { e.stopPropagation(); onDelete() }}
                        className="p-2 bg-white/90 rounded-lg hover:bg-white shadow-sm"
                    >
                        <Trash2 size={14} className="text-gray-600" />
                    </button>
                    <a
                        href={`/guide/${brand.slug}`}
                        target="_blank"
                        onClick={e => e.stopPropagation()}
                        className="p-2 bg-white/90 rounded-lg hover:bg-white shadow-sm"
                    >
                        <ExternalLink size={14} className="text-gray-600" />
                    </a>
                </div>
            </div>

            {/* Content */}
            <div className="p-4">
                <div className="flex items-center gap-3">
                    <div
                        className="w-10 h-10 rounded-lg flex items-center justify-center text-white font-bold"
                        style={{ backgroundColor: brand.primary_color || '#0066FF' }}
                    >
                        {brand.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                        <h3 className="font-semibold text-gray-900">{brand.name}</h3>
                        <p className="text-xs text-gray-400">
                            {brand.published ? 'Published' : 'Draft'}
                        </p>
                    </div>
                </div>
            </div>
        </div>
    )
}

function Modal({ children, onClose, title }: { children: React.ReactNode; onClose: () => void; title: string }) {
    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/50" onClick={onClose} />
            <div className="relative bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl">
                <h2 className="text-xl font-semibold mb-4">{title}</h2>
                {children}
            </div>
        </div>
    )
}

function BrandCardSkeleton() {
    return (
        <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
            {/* Banner Skeleton */}
            <div className="h-32 bg-gray-100 animate-pulse" />

            {/* Content Skeleton */}
            <div className="p-4">
                <div className="flex items-center gap-3">
                    {/* Icon Skeleton */}
                    <div className="w-10 h-10 rounded-lg bg-gray-100 animate-pulse" />

                    {/* Text Skeleton */}
                    <div className="flex-1 space-y-2">
                        <div className="h-4 bg-gray-100 rounded w-1/2 animate-pulse" />
                        <div className="h-3 bg-gray-50 rounded w-1/4 animate-pulse" />
                    </div>
                </div>
            </div>
        </div>
    )
}
