'use client'

import { useState, useEffect, useCallback } from 'react'
import { supabase } from '@/lib/supabase'
import { useAuth } from '@/contexts/AuthContext'

// ============================================
// TYPES
// ============================================

export interface Brand {
    id: string
    workspace_id: string
    name: string
    slug: string
    logo_url: string | null
    banner_url: string | null
    primary_color: string | null
    font_family: string | null
    custom_font_url: string | null
    created_at: string
    updated_at: string
    // Additional fields used in dashboard
    published?: any
    draft?: any
}

export interface CreateBrandInput {
    name: string
    slug?: string
    primary_color?: string
    font_family?: string
    banner_url?: string
}

// ============================================
// HOOK
// ============================================

export function useBrands(workspaceId?: string) {
    const { currentWorkspace } = useAuth()
    const [brands, setBrands] = useState<Brand[]>([])
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)

    // Use provided workspaceId or fall back to current workspace
    const activeWorkspaceId = workspaceId || currentWorkspace?.id

    // ============================================
    // FETCH BRANDS
    // ============================================
    const fetchBrands = useCallback(async () => {
        if (!activeWorkspaceId) {
            setLoading(false)
            setBrands([])
            return
        }

        console.log('[Brands] Fetching for workspace:', activeWorkspaceId)
        setLoading(true)
        setError(null)

        try {
            const { data, error: fetchError } = await supabase
                .from('brands')
                .select('*')
                .eq('workspace_id', activeWorkspaceId)
                .order('created_at', { ascending: false })

            if (fetchError) {
                console.error('[Brands] Fetch error:', fetchError)
                setError(fetchError.message)
                setBrands([])
            } else {
                console.log('[Brands] Found:', data?.length || 0)
                setBrands(data || [])
            }
        } catch (err: any) {
            console.error('[Brands] Exception:', err)
            setError(err.message)
            setBrands([])
        } finally {
            setLoading(false)
        }
    }, [activeWorkspaceId])

    // ============================================
    // CREATE BRAND
    // ============================================
    const createBrand = async (input: CreateBrandInput): Promise<{ data: Brand | null; error: Error | null }> => {
        if (!activeWorkspaceId) {
            return { data: null, error: new Error('No workspace selected') }
        }

        try {
            const slug = input.slug || input.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')

            const { data, error: insertError } = await supabase
                .from('brands')
                .insert({
                    workspace_id: activeWorkspaceId,
                    name: input.name,
                    slug,
                    primary_color: input.primary_color || '#0066FF',
                    font_family: input.font_family || 'Geist',
                    banner_url: input.banner_url || null
                })
                .select()
                .single()

            if (insertError) {
                return { data: null, error: insertError }
            }

            // Create empty draft for the brand
            await supabase
                .from('brand_drafts')
                .insert({
                    brand_id: data.id,
                    content: { sections: getDefaultSections() }
                })

            // Refresh the list
            await fetchBrands()

            return { data, error: null }
        } catch (err) {
            return { data: null, error: err as Error }
        }
    }

    // ============================================
    // UPDATE BRAND
    // ============================================
    const updateBrand = async (brandId: string, updates: Partial<Brand>): Promise<{ error: Error | null }> => {
        try {
            const { error: updateError } = await supabase
                .from('brands')
                .update(updates)
                .eq('id', brandId)

            if (updateError) {
                return { error: updateError }
            }

            await fetchBrands()
            return { error: null }
        } catch (err) {
            return { error: err as Error }
        }
    }

    // ============================================
    // DELETE BRAND
    // ============================================
    const deleteBrand = async (brandId: string): Promise<{ error: Error | null }> => {
        try {
            const { error: deleteError } = await supabase
                .from('brands')
                .delete()
                .eq('id', brandId)

            if (deleteError) {
                return { error: deleteError }
            }

            await fetchBrands()
            return { error: null }
        } catch (err) {
            return { error: err as Error }
        }
    }

    // ============================================
    // EFFECTS
    // ============================================
    useEffect(() => {
        fetchBrands()
    }, [fetchBrands])

    return {
        brands,
        loading,
        error,
        fetchBrands,
        createBrand,
        updateBrand,
        deleteBrand
    }
}

// ============================================
// DEFAULT SECTIONS FOR NEW BRANDS
// ============================================
function getDefaultSections() {
    return [
        {
            id: 'section-intro',
            slug: 'introduction',
            title: 'Introduction',
            blocks: [
                {
                    id: 'block-welcome',
                    type: 'text',
                    content: '<h1>Welcome to Your Brand Guide</h1><p>This is your brand\'s central source of truth. Add your logo, colors, typography, and more to create a comprehensive brand guide.</p>'
                }
            ]
        }
    ]
}
